CREATE TABLE IF NOT EXISTS user_notifications (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL, title VARCHAR(255) NOT NULL, message TEXT NOT NULL, is_read BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS certifications (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL, assessment_id BIGINT NOT NULL, title VARCHAR(255) NOT NULL, verification_code VARCHAR(100) NOT NULL UNIQUE, score DOUBLE PRECISION NOT NULL, issued_at TIMESTAMP WITH TIME ZONE NOT NULL, CONSTRAINT uq_certification_assessment UNIQUE(user_id,assessment_id));
